select a.json:LAST_CUUPDATE_DATE::TIMESTAMP_TZ as last_cuupdate_date,a.json:MAILING_STATE::TEXT(1100) as mailing_state,a.json:OTHER_CITY::TEXT(1000) as other_city,a.json:LEAD_SOURCE::TEXT(1600) as lead_source,a.json:LAST_ACTIVITY_DATE::DATE as last_activity_date,a.json:SALUTATION::TEXT(1000) as salutation,a.json:MAILING_STREET::TEXT(1600) as mailing_street,a.json:JIGSAW_CONTACT_ID::TEXT(900) as jigsaw_contact_id,a.json:LAST_VIEWED_DATE::TIMESTAMP_TZ as last_viewed_date,a.json:JIGSAW::TEXT(900) as jigsaw,a.json:OTHER_STREET::TEXT(1600) as other_street,a.json:MAILING_LATITUDE::FLOAT as mailing_latitude,a.json:LAST_MODIFIED_DATE::TIMESTAMP_TZ as last_modified_date,a.json:MIDDLE_NAME::TEXT(1000) as middle_name,a.json:PHOTO_URL::TEXT(1600) as photo_url,a.json:EMAIL_BOUNCED_DATE::TIMESTAMP_TZ as email_bounced_date,a.json:LAST_NAME::TEXT(1100) as last_name,a.json:IS_PRIORITY_RECORD::BOOLEAN as is_priority_record,a.json:CREATED_DATE::TIMESTAMP_TZ as created_date,a.json:OWNER_ID::TEXT(900) as owner_id,a.json:MASTER_RECORD_ID::TEXT(900) as master_record_id,a.json:LAST_MODIFIED_BY_ID::TEXT(900) as last_modified_by_id,a.json:IS_PERSON_ACCOUNT::BOOLEAN as is_person_account,a.json:REPORTS_TO_ID::TEXT(900) as reports_to_id,a.json:FIRST_NAME::TEXT(1000) as first_name,a.json:IS_DELETED::BOOLEAN as is_deleted,a.json:OTHER_STATE::TEXT(1100) as other_state,a.json:PHONE::TEXT(1000) as phone,a.json:EMAIL_BOUNCED_REASON::TEXT(1600) as email_bounced_reason,a.json:ASSISTANT_PHONE::TEXT(1000) as assistant_phone,a.json:_FIVETRAN_SYNCED::TIMESTAMP_TZ as _fivetran_synced,a.json:REP_ID_C::TEXT(900) as rep_id_c,a.json:CREATED_BY_ID::TEXT(900) as created_by_id,a.json:TITLE::TEXT(1200) as title,a.json:MAILING_POSTAL_CODE::TEXT(900) as mailing_postal_code,a.json:DESCRIPTION::TEXT(96800) as description,a.json:IS_EMAIL_BOUNCED::BOOLEAN as is_email_bounced,a.json:LAST_REFERENCED_DATE::TIMESTAMP_TZ as last_referenced_date,a.json:MOBILE_PHONE::TEXT(1000) as mobile_phone,a.json:MAILING_LONGITUDE::FLOAT as mailing_longitude,a.json:MAILING_COUNTRY::TEXT(1100) as mailing_country,a.json:FAX::TEXT(1000) as fax,a.json:OTHER_POSTAL_CODE::TEXT(900) as other_postal_code,a.json:ID::TEXT(900) as id,a.json:OTHER_GEOCODE_ACCURACY::TEXT(1000) as other_geocode_accuracy,a.json:SUFFIX::TEXT(1000) as suffix,a.json:OTHER_LONGITUDE::FLOAT as other_longitude,a.json:HOME_PHONE::TEXT(1000) as home_phone,a.json:MAILING_GEOCODE_ACCURACY::TEXT(1000) as mailing_geocode_accuracy,a.json:EMAIL::TEXT(1100) as email,a.json:_FIVETRAN_DELETED::BOOLEAN as _fivetran_deleted,a.json:BIRTHDATE::DATE as birthdate,a.json:LAST_CUREQUEST_DATE::TIMESTAMP_TZ as last_curequest_date,a.json:ASSISTANT_NAME::TEXT(1000) as assistant_name,a.json:SYSTEM_MODSTAMP::TIMESTAMP_TZ as system_modstamp,a.json:INDIVIDUAL_ID::TEXT(900) as individual_id,a.json:OTHER_PHONE::TEXT(1000) as other_phone,a.json:OTHER_LATITUDE::FLOAT as other_latitude,a.json:DEPARTMENT::TEXT(1100) as department,a.json:MAILING_CITY::TEXT(1000) as mailing_city,a.json:ACCOUNT_ID::TEXT(900) as account_id,a.json:OTHER_COUNTRY::TEXT(1100) as other_country,a.json:RECORD_TYPE_ID::TEXT(900) as record_type_id,a.json:NAME::TEXT(1200) as name,a.effective_at::timestamp as effective_at,a._created_at::timestamp as _created_at   , {{ col_is_head(
    reference=source('salesforce_baystate', 'contact'),
    source_date_col='a.effective_at',
    reference_date_col='effective_at'
    ) }}
  , case when b.rn = 1 then 1 else 0 end                   as is_latest from {{ source('salesforce_baystate', 'contact') }} a left join (
  select effective_at::date as effective_at, _created_at as _created_at, row_number() over(partition by effective_at::date order by _created_at desc) as rn
  from {{ source('salesforce_baystate', 'contact') }} group by 1,2
) b
on a.effective_at::date = b.effective_at::date
    and a._created_at = b._created_at
